/* @author MILO-GAO(高振銘)@2020 */ package page2020.view;import java.util.ArrayList;import java.util.Arrays;import java.util.List;import org.slf4j.Logger;import org.slf4j.LoggerFactory;import page2020.util.EmptyUtil;public class Element<T, C extends Content<?>> extends Tag<T> {	private static Logger log = LoggerFactory.getLogger(Element.class);	private List<C> contents = new ArrayList<C>();	public Element() {		super(ContentType.element);	}	public Element(Integer type) {		super(type);	}	public Element(String tagName) {		super(tagName, ContentType.element);	}	public Element(String tagName, Integer type) {		super(tagName, type);	}	public T append(C c) {		if (this.isContent(c)) {			this.contents.add(c);		} else {			log.error("append: argument(c) is invalid !");		}		return super.bean();	}	@SuppressWarnings("unchecked")	public T append(C... c) {		if (EmptyUtil.not((Object[]) c)) {			Arrays.asList(c).forEach(item -> this.append(item));		} else {			log.error("append: argument(c) is empty !");		}		return super.bean();	}	public T append(List<C> c) {		if (EmptyUtil.not(c)) {			c.forEach(item -> this.append(item));		} else {			log.error("append: argument(c) is empty !");		}		return super.bean();	}	public T text(String text) {		@SuppressWarnings("unchecked")		C c = (C) new Value().text(text);		this.append(c);		return super.bean();	}	public T value(Object value) {		@SuppressWarnings("unchecked")		C c = (C) new Value().value(value);		this.append(c);		return super.bean();	}	public T code(String code) {		@SuppressWarnings("unchecked")		C c = (C) new Text().code(code);		this.append(c);		return super.bean();			}	public T code(String code, Object... args) {		@SuppressWarnings("unchecked")		C c = (C) new Text().code(code, args);		this.append(c);		return super.bean();			}	public T icon(String icon) {		@SuppressWarnings("unchecked")		C c = (C) new Text().icon(icon);		this.append(c);		return super.bean();	}	public T empty() {		this.contents.clear();		return super.bean();	}	public C get(int index) {		if (index >= 0 && index < this.contents.size()) {			return this.contents.get(index);		} else {			log.error("get: argument(index) is out of range !");		}		return null;	}	public C add(int index, Content<?> c) {		if (index >= 0 && index < this.contents.size() && c != null) {			@SuppressWarnings("unchecked")			C content = (C) c;			this.contents.add(index, content);			return content;		} else {			log.error("add: argument(index, c) are out of range or empty !");		}		return null;	}	public C set(int index, Content<?> c) {		if (index >= 0 && index < this.contents.size() && c != null) {			@SuppressWarnings("unchecked")			C content = (C) c;			this.contents.add(index, content);			return this.contents.remove(index + 1);		} else {			log.error("set: argument(index, c) are out of range or empty !");		}		return null;	}	public C remove(int index) {		if (index >= 0 && index < this.contents.size()) {			return this.contents.remove(index);		} else {			log.error("remove: argument(index) is out of range !");		}		return null;	}	public C remove(String name) {		int i = this.contents.size() - 1;		while (i >= 0) {			Content<?> c = this.contents.get(i);			if (EmptyUtil.not(c.getName()) && c.getName().equals(name)) {				return this.contents.remove(i);			} else {				i -= 1;			}		}		return null;	}	public C last() {		if (this.contents.size() > 0) {			return this.contents.get(this.contents.size() - 1);		}		return null;	}	public int count() {		return this.contents.size();	}	public int index(String name, String tagName, String className) {		int size = this.contents.size();		for (int i=0; i < size; i++) {			Content<?> c = this.contents.get(i);			if (EmptyUtil.not(name) && (! name.equals(c.getName()))) {				continue;			}			if (! (c instanceof Tag<?>)) {				continue;			}			Tag<?> tag = (Tag<?>) c;			if (EmptyUtil.not(tagName) && (! tagName.equals(tag.getTagName()))) {				continue;			}			if (EmptyUtil.not(className) && (! tag.hasClass(className))) {				continue;			}			return i;		}		return -1;	}	public int index(String dataKey, String dataValue) {		int size = this.contents.size();		for (int i=0; i < size; i++) {			Content<?> c = this.contents.get(i);			if (! (c instanceof Tag<?>)) {				continue;			}			Tag<?> tag = (Tag<?>) c;			Object value = tag.getData(dataKey);			if (value != null && value.equals(dataValue)) {				return i;			}		}		return -1;	}	public Content<?> find(String name, String tagName, String className) {		int index = this.index(name, tagName, className);		if (index >= 0) {			return this.contents.get(index);		}		int size = this.contents.size();		for (int i=0; i < size; i++) {			Content<?> c = this.contents.get(i);			if (c instanceof Element) {				Element<?, ?> element = (Element<?, ?>) c;				if (element.count() > 0) {					Content<?> content = element.find(name, tagName, className);					if (content != null) {						return content;					}				}			}		}		return null;	}	public Content<?> find(String name) {		return this.find(name, null, null);	}	public Content<?> find(String dataKey, String dataValue) {		int index = this.index(dataKey, dataValue);		if (index >= 0) {			return this.contents.get(index);		}		int size = this.contents.size();		for (int i=0; i < size; i++) {			Content<?> c = this.contents.get(i);			if (c instanceof Element) {				Element<?, ?> element = (Element<?, ?>) c;				if (element.count() > 0) {					Content<?> content = element.find(dataKey, dataValue);					if (content != null) {						return content;					}				}			}		}		return null;	}	public List<Content<?>> findAll(String name) {		List<Content<?>> contents = new ArrayList<Content<?>>();		if (EmptyUtil.not(name)) {			this.findAll(name, contents);		}		return contents;	}	public boolean replace(Content<?> origin, List<Content<?>> newList) {		int count = this.count();		for (int i=0; i < count; i++) {			if (origin == this.get(i)) {				this.remove(i);				count -= 1;				int size = newList.size();				if (i < count) {					for (int j=0; j < size; j++) {						@SuppressWarnings("unchecked")						C c = (C) newList.get(j);						this.contents.add((i + j), c);					}				} else {					for (int j=0; j < size; j++) {						@SuppressWarnings("unchecked")						C c = (C) newList.get(j);						this.contents.add(c);					}									}				return true;			}		}		int size = this.contents.size();		for (int i=0; i < size; i++) {			Content<?> c = this.contents.get(i);			if (c instanceof Element) {				Element<?, ?> element = (Element<?, ?>) c;				if (element.count() > 0) {					if (element.replace(origin, newList)) {						return true;					}				}			}		}		return false;			}	public T prop(String attribute) {		if (EmptyUtil.not(attribute)) {			super.getAttrSet().add(attribute);		} else {			log.error("prop: argument(attributre) has empty !");		}		return super.bean();	}	public T prop(String name, Object value) {		if (EmptyUtil.not(name) && EmptyUtil.not(value)) {			super.getAttrMap().put(name, value);		} else {			log.error("prop: argument(name, value) has empty !");		}		return super.bean();	}	public T codex(String code) {		if (EmptyUtil.not(code)) {			@SuppressWarnings("unchecked")			C content = (C) new Text().text(code);			this.append(content);		} else {			log.error("codex: argument(code) has empty !");		}		return super.bean();			}	@Override	public void build() {		super.build();		if (! this.contents.isEmpty()) {			this.contents.forEach(c -> {				if (c instanceof Tag<?>) {					((Tag<?>) c).build();				}			});		}	}	@Override	public T copy() {		T bean = super.copy();		List<C> contents = new ArrayList<C>();		if (! this.contents.isEmpty()) {			this.contents.forEach(c -> {				@SuppressWarnings("unchecked")				C copy = (C) c.copy();				contents.add(copy);							});		}		@SuppressWarnings("unchecked")		Element<T, C> element = (Element<T, C>) bean;		element.setContents(contents);		return (T) bean;	}	protected boolean isContent(C c) {		if (c != null) {			return true;		}		log.error("Element: content is null !");		return false;	}	private void findAll(String name, List<Content<?>> contents) {		int size = this.contents.size();		for (int i=0; i < size; i++) {			Content<?> c = this.contents.get(i);			if (name.equals(c.getName())) {				contents.add(c);			}			if (c instanceof Element<?, ?>) {				Element<?, ?> e = (Element<?, ?>) c;				e.findAll(name, contents);			}		}	}	public List<C> getContents() {		return contents;	}	public void setContents(List<C> contents) {		this.contents = contents;	}}